#include <iostream>#include <string>using namespace std;class Vehicle {protected:    string regNo;    double dailyRate;public:    Vehicle(string r, double d) {        regNo = r;        dailyRate = d;    }    virtual double charge(int days) = 0;    virtual void display() {        cout << "Registration: " << regNo << endl;        cout << "Rental Charge: " << charge(1) << endl;    }    virtual ~Vehicle() {}};class Bicycle : public Vehicle {public:    Bicycle(string r, double d) : Vehicle(r, d) {}    double charge(int days) override {        return dailyRate * days;    }};class TwoWheeler : public Vehicle {public:    TwoWheeler(string r, double d) : Vehicle(r, d) {}    double charge(int days) override {        return dailyRate * days + 50;    }};class Car : public Vehicle {protected:    int seats;public:    Car(string r, double d, int s)        : Vehicle(r, d) {        seats = s;    }    double charge(int days) override {        return dailyRate * days + 200;    }};class ElectricCar : public Car {    double batteryCapacity;public:    ElectricCar(string r, double d, int s, double b)        : Car(r, d, s) {        batteryCapacity = b;    }    double charge(int days) override {        return dailyRate * days + batteryCapacity * 5;    }};int main() {    Vehicle* fleet[4];    fleet[0] = new Bicycle("B101", 100);    fleet[1] = new TwoWheeler("T102", 200);    fleet[2] = new Car("C103", 1000, 5);    fleet[3] = new ElectricCar("E104", 1500, 5, 50);    for (int i = 0; i < 4; i++) {        fleet[i]->display();        cout << endl;    }    for (int i = 0; i < 4; i++) {        delete fleet[i];    }    return 0;}